{
    if(ctx == NULL) return 1;

    int ret, discard;
    int prev_was_idat = 1;
    struct spng_chunk chunk;
    unsigned char *data;

    memcpy(&chunk, &ctx->last_idat, sizeof(struct spng_chunk));

    while( !(ret = read_header(ctx, &discard)))
    {
        memcpy(&chunk, &ctx->current_chunk, sizeof(struct spng_chunk));

